s=open(p).read()
old_start = s.index("    private static dimensionFunctionMap = {")
old_end = s.index("    static buildAggregationQueries = async ({")
new_block = '''    /**
     * The readings one group of a dimension holds inside a window, alongside the
     * level it was already standing at when the window opened. Only a dimension
     * that carries its level needs the earlier lookup, and the lookup reaches
     * back to the beginning of time so a level set long ago is not lost.
     */
    private static readGroup = async ({
        seriesSet,
        startTime,
        endTime,
        carryForward,
        method,
    }: {
        seriesSet: UsageSeries[];
        startTime: Date;
        endTime: Date;
        carryForward: boolean;
        method: aggregationMethod;
    }): Promise<{ samples: UsageSample[]; standingLevel?: number }> => {
        const samples: UsageSample[] = [];
        const standingLevels: number[] = [];
        for (const series of seriesSet) {
            samples.push(...(await readUsageSamples({ series, startTime, endTime })));
            if (carryForward) {
                const priorLevel = standingLevelOf(
                    await readUsageSamples({ series, startTime: START_OF_TIME, endTime: startTime }),
                );
                if (priorLevel !== undefined) {
                    standingLevels.push(priorLevel);
                }
            }
        }
        return {
            samples,
            standingLevel: standingLevels.length ? reduceSamples(standingLevels, method) : undefined,
        };
    };

    private static dimensionFunctionMap = {
        [usageData]: async ({
            businessID,
            startTime,
            endTime,
            dimension,
            customerId,
        }: SingleUsageEvent): Promise<BasicUsageDocument[] | DimensionUsageCurve[]> => {
            const {
                dimensionId,
                aggregationInterval: argumentAgg,
                aggregationMethod: argumentAggregationMethod,
                sampleType,
            } = dimension as ReadDimensionResponseData;
            const published = await listUsageSeries({ businessID, customerId, dimensionId });

            if (argumentAgg !== aggregationInterval.none) {
                const windowStart = new Date(startTime);
                const windowEnd = new Date(endTime);
                const steps = stepsOfWindow({ startTime: windowStart, endTime: windowEnd, interval: argumentAgg });
                const carryForward = carriesStandingLevel(sampleType);
                const curveOf = async (seriesSet: UsageSeries[], metadataGroup?: Record<string, string>) => {
                    const { samples, standingLevel } = await UsageAggregationEvent.readGroup({
                        seriesSet,
                        startTime: windowStart,
                        endTime: windowEnd,
                        carryForward,
                        method: argumentAggregationMethod,
                    });
                    return {
                        metadataGroup,
                        usage: curveOfSteps({
                            steps,
                            samples,
                            method: argumentAggregationMethod,
                            carryForward,
                            standingLevel,
                            metadataGroup,
                        }),
                    } as DimensionUsageCurve;
                };

                // A dimension priced by metadata is reported one published group at
                // a time, so each group keeps its own curve.
                if (pricedByMetadataGroup(dimension as ReadDimensionResponseData) && published.length) {
                    const curves: DimensionUsageCurve[] = [];
                    for (const series of published) {
                        const metadata = metadataOf(series);
                        curves.push(await curveOf([series], Object.keys(metadata).length ? metadata : undefined));
                    }
                    return curves;
                }

                // Anything else reports a single curve, even for a customer without
                // a single reading, so every step of the window is accounted for.
                return [await curveOf(published)];
            }

            const unAggregatedResults: BasicUsageDocument[] = [];
            for (const series of published) {
                const samples = await readUsageSamples({
                    series,
                    startTime: new Date(startTime),
                    endTime: new Date(endTime),
                });
                const metadata = metadataOf(series);
                samples.forEach(({ timestamp, value }) => {
                    unAggregatedResults.push({ timestamp, recordValue: value.toString(), metadata });
                });
            }
            return unAggregatedResults as BasicUsageDocument[];
        },
    };

'''
s = s[:old_start] + new_block + s[old_end:]

old_bq_start = s.index("    static buildAggregationQueries = async ({")
old_bq_end = s.index("    static getAggregateUsageForDimension = async (")
new_bq = '''    static buildAggregationQueries = async ({
        offeringDocument,
        ...rest
    }: UsageAggregationEvent): Promise<
        Array<UnAggregatedUsageResponse | AggregatedUsageResponse | MetadataGroupedAggregatedUsageResponse[]>
    > => {
        const results = await Promise.all(
            offeringDocument.dimensions.map(async ({ dimensionId, ...dimensionRest }) => {
                const offeringId = offeringDocument?.offeringId;
                const usage = await UsageAggregationEvent.dimensionFunctionMap['usageData']({
                    dimension: { ...dimensionRest, dimensionId },
                    ...rest,
                });
                if (isCurveSet(usage)) {
                    return usage.map(({ metadataGroup, usage: curve }) => ({
                        offeringId,
                        dimensionId,
                        ...(metadataGroup ? { metadataGroup } : {}),
                        usage: curve,
                    })) as MetadataGroupedAggregatedUsageResponse[];
                }
                return { offeringId, dimensionId, usage };
            }),
        );
        return results as Array<UnAggregatedUsageResponse | AggregatedUsageResponse>;
    };

'''
