import { aggregationInterval, aggregationMethod, SampleType } from '../dimensions/dto/create-dimension.dto.js';
import { carriesStandingLevel, curveOfSteps, latestSampleOf, stepsOfWindow } from './usageCurve.js';

const step = (startTime: string, endTime: string) => ({ start: new Date(startTime), end: new Date(endTime) });
const reading = (timestamp: string, value: number) => ({ timestamp, value });

describe('usage curve steps', () => {
    it('walks a window in clock aligned steps clamped to the window', () => {
        const steps = stepsOfWindow({
            startTime: new Date('2024-02-14T00:20:00.000Z'),
            endTime: new Date('2024-02-14T02:30:00.000Z'),
            interval: aggregationInterval.hour,
        });
        expect(steps.map(({ start, end }) => [start.toISOString(), end.toISOString()])).toEqual([
            ['2024-02-14T00:20:00.000Z', '2024-02-14T01:00:00.000Z'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z'],
            ['2024-02-14T02:00:00.000Z', '2024-02-14T02:30:00.000Z'],
        ]);
    });

    it('steps whole days on the clock', () => {
        const steps = stepsOfWindow({
            startTime: new Date('2024-02-14T06:00:00.000Z'),
            endTime: new Date('2024-02-16T00:00:00.000Z'),
            interval: aggregationInterval.day,
        });
        expect(steps.map(({ start, end }) => [start.toISOString(), end.toISOString()])).toEqual([
            ['2024-02-14T06:00:00.000Z', '2024-02-15T00:00:00.000Z'],
            ['2024-02-15T00:00:00.000Z', '2024-02-16T00:00:00.000Z'],
        ]);
    });

    it('steps whole months on the clock, leap years included', () => {
        const steps = stepsOfWindow({
            startTime: new Date('2024-01-15T00:00:00.000Z'),
            endTime: new Date('2024-03-10T00:00:00.000Z'),
            interval: aggregationInterval.month,
        });
        expect(steps.map(({ start, end }) => [start.toISOString(), end.toISOString()])).toEqual([
            ['2024-01-15T00:00:00.000Z', '2024-02-01T00:00:00.000Z'],
            ['2024-02-01T00:00:00.000Z', '2024-03-01T00:00:00.000Z'],
            ['2024-03-01T00:00:00.000Z', '2024-03-10T00:00:00.000Z'],
        ]);
    });

    it('leaves a window whole when no stepping was asked for', () => {
        expect(
            stepsOfWindow({
                startTime: new Date('2024-02-14T00:20:00.000Z'),
                endTime: new Date('2024-02-14T02:30:00.000Z'),
                interval: undefined,
            }),
        ).toHaveLength(1);
    });

    it('has no steps for an empty window', () => {
        expect(
            stepsOfWindow({
                startTime: new Date('2024-02-14T00:00:00.000Z'),
                endTime: new Date('2024-02-14T00:00:00.000Z'),
                interval: aggregationInterval.hour,
            }),
        ).toEqual([]);
    });
});

describe('usage curve values', () => {
    const steps = [
        step('2024-02-14T00:00:00.000Z', '2024-02-14T01:00:00.000Z'),
        step('2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z'),
        step('2024-02-14T02:00:00.000Z', '2024-02-14T03:00:00.000Z'),
    ];

    it('reports every step, zero where nothing was used', () => {
        const curve = curveOfSteps({
            steps,
            samples: [reading('2024-02-14T00:10:00.000Z', 2), reading('2024-02-14T00:40:00.000Z', 3)],
            method: aggregationMethod.sum,
        });
        expect(curve.map(({ value }) => value)).toEqual(['5', '0', '0']);
        expect(curve[1]).toEqual({
            value: '0',
            startTime: '2024-02-14T01:00:00.000Z',
            endTime: '2024-02-14T02:00:00.000Z',
        });
    });

    it('carries a standing level through steps without a reading', () => {
        const curve = curveOfSteps({
            steps,
            samples: [reading('2024-02-14T00:10:00.000Z', 4)],
            method: aggregationMethod.last,
            carryForward: true,
        });
        expect(curve.map(({ value }) => value)).toEqual(['4', '4', '4']);
    });

    it('carries a level set before the window opened', () => {
        const curve = curveOfSteps({
            steps,
            samples: [],
            method: aggregationMethod.last,
            carryForward: true,
            standingLevel: 6,
        });
        expect(curve.map(({ value }) => value)).toEqual(['6', '6', '6']);
    });

    it('reports zero for a level that was never set', () => {
        const curve = curveOfSteps({ steps, samples: [], method: aggregationMethod.last, carryForward: true });
        expect(curve.map(({ value }) => value)).toEqual(['0', '0', '0']);
    });

    it('applies the aggregation method of the dimension inside a step', () => {
        const samples = [reading('2024-02-14T01:10:00.000Z', 5), reading('2024-02-14T01:20:00.000Z', 15)];
        expect(curveOfSteps({ steps, samples, method: aggregationMethod.max })[1].value).toBe('15');
        expect(curveOfSteps({ steps, samples, method: aggregationMethod.min })[1].value).toBe('5');
        expect(curveOfSteps({ steps, samples, method: aggregationMethod.average })[1].value).toBe('10');
        expect(curveOfSteps({ steps, samples, method: aggregationMethod.count })[1].value).toBe('2');
        expect(curveOfSteps({ steps, samples, method: aggregationMethod.last })[1].value).toBe('15');
    });

    it('knows which dimensions stand at a level', () => {
        expect(carriesStandingLevel(SampleType.continious)).toBe(true);
        expect(carriesStandingLevel(SampleType.gauge)).toBe(false);
        expect(carriesStandingLevel(undefined)).toBe(false);
    });

    it('picks the newest reading as the level a series was left at', () => {
        expect(
            latestSampleOf([reading('2024-02-14T02:00:00.000Z', 1), reading('2024-02-14T03:00:00.000Z', 8)]),
        ).toEqual(reading('2024-02-14T03:00:00.000Z', 8));
        expect(latestSampleOf([])).toBeUndefined();
    });
});
