  "output": "import { aggregationInterval, aggregationMethod, SampleType } from '../dimensions/dto/create-dimension.dto.js';
import { UsageSample } from '../utils/aws/cloudwatchUsage.js';
import { UsageDocument } from './dto/read-usage.dto.js';

/** One step of the curve a window is reported in, already clamped to the window. */
export type UsageStep = { start: Date; end: Date };

/** What a dimension's aggregation method makes of a set of readings. */
export const reduceSamples = (values: number[], method: aggregationMethod): number => {
    if (values.length === 0) {
        return 0;
    }
    switch (method) {
        case aggregationMethod.max:
            return Math.max(...values);
        case aggregationMethod.min:
            return Math.min(...values);
        case aggregationMethod.average:
            return values.reduce((total, value) => total + value, 0) / values.length;
        case aggregationMethod.count:
            return values.length;
        case aggregationMethod.last:
            return values[values.length - 1];
        default:
            return values.reduce((total, value) => total + value, 0);
    }
};

/** Whether an interval asks for a curve at all, or for the window as a whole. */
export const isSteppedInterval = (interval: aggregationInterval): boolean =>
    interval === aggregationInterval.hour ||
    interval === aggregationInterval.day ||
    interval === aggregationInterval.month;

/** The clock aligned edge an instant belongs to for a given step size. */
export const alignedEdge = (instant: Date, interval: aggregationInterval): Date => {
    switch (interval) {
        case aggregationInterval.month:
            return new Date(Date.UTC(instant.getUTCFullYear(), instant.getUTCMonth(), 1));
        case aggregationInterval.day:
            return new Date(Date.UTC(instant.getUTCFullYear(), instant.getUTCMonth(), instant.getUTCDate()));
        default:
            return new Date(
                Date.UTC(instant.getUTCFullYear(), instant.getUTCMonth(), instant.getUTCDate(), instant.getUTCHours()),
            );
    }
};

/** The clock aligned edge following the one handed in. */
const nextEdge = (edge: Date, interval: aggregationInterval): Date => {
    switch (interval) {
        case aggregationInterval.month:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth() + 1, 1));
        case aggregationInterval.day:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth(), edge.getUTCDate() + 1));
        default:
            return new Date(
                Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth(), edge.getUTCDate(), edge.getUTCHours() + 1),
            );
    }
};

/**
 * The steps a window is reported in. Edges sit on the clock for the step size
 * asked for, and the first and the last step are clamped to the window itself,
 * so the curve never reaches outside of what was requested. An interval that
 * asks for no stepping at all leaves the window whole.
 */
export const stepsOfWindow = ({
    startTime,
    endTime,
    interval,
}: {
    startTime: Date;
    endTime: Date;
    interval: aggregationInterval;
}): UsageStep[] => {
    const start = startTime.getTime();
    const end = endTime.getTime();
    if (!(end > start)) {
        return [];
    }
    if (!isSteppedInterval(interval)) {
        return [{ start: new Date(start), end: new Date(end) }];
    }
    const steps: UsageStep[] = [];
    let edge = alignedEdge(new Date(start), interval);
    while (edge.getTime() < end) {
        const following = nextEdge(edge, interval);
        steps.push({
            start: edge.getTime() < start ? new Date(start) : edge,
            end: following.getTime() > end ? new Date(end) : following,
        });
        edge = following;
    }
    return steps;
};

/** Readings oldest first, the order a curve is walked in. */
export const orderSamples = (samples: UsageSample[]): UsageSample[] =>
    [...samples].sort((left, right) => new Date(left.timestamp).getTime() - new Date(right.timestamp).getTime());

/** The newest of a set of readings, the one a series was left standing at. */
export const latestSampleOf = (samples: UsageSample[]): UsageSample | undefined => {
    const ordered = orderSamples(samples);
    return ordered.length ? ordered[ordered.length - 1] : undefined;
};

/** A dimension whose readings state a level that stands until the next one. */
export const carriesStandingLevel = (sampleType: SampleType): boolean => sampleType === SampleType.continious;

/**
 * The curve of one series over the steps of a window. Every step is reported,
 * whether or not it holds a reading. A dimension that carries a standing level
 * repeats the level it was left at, which may have been set however long before
 * the window; anything else is unused in a step it holds no reading for and so
 * reports zero.
 */
export const curveOfSteps = ({
    steps,
    samples,
    method,
    carryForward = false,
    standingLevel,
}: {
    steps: UsageStep[];
    samples: UsageSample[];
    method: aggregationMethod;
    carryForward?: boolean;
    standingLevel?: number;
}): UsageDocument[] => {
    const ordered = orderSamples(samples);
    let cursor = 0;
    let level = standingLevel;
    return steps.map(({ start, end }) => {
        const readings: number[] = [];
        while (cursor < ordered.length && new Date(ordered[cursor].timestamp).getTime() < end.getTime()) {
            const { timestamp, value } = ordered[cursor];
            if (new Date(timestamp).getTime() >= start.getTime()) {
                readings.push(value);
            } else if (carryForward) {
                level = value;
            }
            cursor++;
        }
        let value: number;
        if (readings.length) {
            value = reduceSamples(readings, method);
            level = readings[readings.length - 1];
        } else {
            value = carryForward && level !== undefined ? level : 0;
        }
        return new UsageDocument({
            value: `${value}`,
            startTime: start.toISOString(),
            endTime: end.toISOString(),
        });
    });
};
"
}

